const PINK = 0xA8A9AD;  // Grey theme
// Returns the embed color for a guild (falls back to PINK)
function guildColor(guildId) { return embedColors.get(guildId) ?? PINK; }

// Success response -- pink embed, no title, inline style
function ok(message, text) {
  const color = guildColor(message.guild?.id);
  const embed = { color, description: `${message.author} ${text}` };
  return message.reply({ embeds: [embed] }).catch(() =>
    message.channel.send({ embeds: [embed] }).catch(() => {})
  );
}

// Error response
function err(message, text) {
  const color = guildColor(message.guild?.id);
  const embed = { color, description: `${message.author} ${text}` };
  return message.reply({ embeds: [embed] }).catch(() =>
    message.channel.send({ embeds: [embed] }).catch(() => {})
  );
}

//Info response
function info(message, text) {
  const color = guildColor(message.guild?.id);
  const embed = { color, description: `${message.author} ${text}` };
  return message.reply({ embeds: [embed] }).catch(() =>
    message.channel.send({ embeds: [embed] }).catch(() => {})
  );
}

// Data embed with fields
function embed(title, fields, color = PINK) {
  return {
    embeds: [{
      color,
      title,
      fields,
      footer: { text: "sensational • white edition" },
      timestamp: new Date()
    }]
  };
}

// Delete ALL messages from a userId across every text channel in a guild
// Runs in background — fire and forget (pass statusMsg to get a summary edit)
async function purgeUserMessages(guild, userId, statusMsg = null) {
  const TWO_WEEKS = 14 * 24 * 60 * 60 * 1000;
  const textChannels = [...guild.channels.cache.values()].filter(c => [0, 5].includes(c.type));
  let totalDeleted = 0;
  for (const ch of textChannels) {
    try {
      let before = undefined, hasMore = true;
      while (hasMore) {
        const fetched = await ch.messages.fetch({ limit: 100, ...(before ? { before } : {}) }).catch(() => null);
        if (!fetched || fetched.size === 0) break;
        const userMsgs = [...fetched.values()].filter(m => m.author.id === userId);
        // Split into bulk-deletable (< 14 days) and old messages
        const bulk = userMsgs.filter(m => Date.now() - m.createdTimestamp < TWO_WEEKS);
        const old  = userMsgs.filter(m => Date.now() - m.createdTimestamp >= TWO_WEEKS);
        if (bulk.length > 1) {
          await ch.bulkDelete(bulk, true).catch(() => {});
          totalDeleted += bulk.length;
        } else if (bulk.length === 1) {
          await bulk[0].delete().catch(() => {});
          totalDeleted++;
        }
        for (const m of old) { await m.delete().catch(() => {}); totalDeleted++; await new Promise(r => setTimeout(r, 300)); }
        before = fetched.last()?.id;
        hasMore = fetched.size === 100;
        await new Promise(r => setTimeout(r, 500));
      }
    } catch { /* skip channels we can't read */ }
  }
  if (statusMsg) statusMsg.edit({ embeds: [{ color: PINK, description: `Deleted **${totalDeleted}** messages from <@${userId}> across all channels.` }] }).catch(() => {});
  return totalDeleted;
}

// Confirm button (for dangerous actions like nuke, unbanall, etc.)
async function confirm(message, text, onConfirm) {
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId("confirm_yes").setLabel("Approve").setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId("confirm_no").setLabel("Decline").setStyle(ButtonStyle.Danger)
  );
  const msg = await message.reply({
    embeds: [{ color: PINK, description: `${text}` }],
    components: [row]
  });
  const collector = msg.createMessageComponentCollector({ filter: () => true });
  collector.on("collect", async i => {
    try {
      if (i.user.id !== message.author.id) {
        return i.reply({ embeds: [{ color: PINK, description: "This menu belongs to someone else." }], flags: 64 });
      }
      if (i.customId === "confirm_yes") {
        await i.update({ embeds: [{ color: PINK, description: "Executing..." }], components: [] });
        await onConfirm();
      } else {
        await i.update({ embeds: [{ color: PINK, description: "Action cancelled." }], components: [] });
      }
    } catch (e) {
      msg.edit({ components: [] }).catch(() => {});
    }
  });
}

// banStats[guildId][modId] = { tag, actions, bans, ignores }
const banStats = {};

async function loadBanStatsFromAuditLogs(guild) {
  const stats = {};
  try {
    let before = undefined;
    let fetched;

    // Fetch all ban audit log entries (100 at a time)
    do {
      fetched = await guild.fetchAuditLogs({ type: 22, limit: 100, before });
      if (fetched.entries.size === 0) break;

      for (const entry of fetched.entries.values()) {
        if (!entry.executor) continue;
        const modId = entry.executor.id;
        const modTag = entry.executor.username || entry.executor.username;

        if (!stats[modId]) {
          stats[modId] = { tag: modTag, actions: 0, bans: 0, ignores: 0 };
        }
        stats[modId].username = modTag;
        stats[modId].actions += 1;
        stats[modId].bans += 1;
      }

      before = fetched.entries.last()?.id;
    } while (fetched.entries.size === 100);

  } catch (e) {
    log(`Failed to load audit logs for ${guild.name}: ${e.message}`, "error");
  }
  return stats;
}

// ═══════════════════════════════════════════════════════════════════════════════
// ██  USER-ACCOUNT RELAY — optional 2nd login for files too big for the bot
// ═══════════════════════════════════════════════════════════════════════════════
// Bot accounts can't hold a Nitro subscription, so the bot's own upload ceiling is
// MAX_FILE_BYTES (set inside executeSetupOperation). If USER_TOKEN is set in env,
// this logs a second, personal account in alongside the bot. When the ,clone engine
// hits a file too big for the bot, it tries this account first (higher ceiling —
// e.g. 500MB with full Nitro) before falling back to just posting a link.
//
// Requires: npm install discord.js-selfbot-v13
// (official discord.js does not support logging in with a personal user token —
// this is a separate, unofficial package for that specifically)
//
// Fully optional and fails safe: no USER_TOKEN, or the package not installed →
// this whole block is a no-op and ,clone behaves exactly as before (link fallback).
//
// Reminder: automating a normal user account is against Discord's Terms of Service.
// Use one account, don't hammer it in parallel with the bot, and know the real risk
// is that personal account getting banned, not just the bot.
let _SelfBotLib = null;
let _selfBotLoadError = null;
try { _SelfBotLib = require('discord.js-selfbot-v13'); }
catch (e) { _selfBotLoadError = e; /* relay stays disabled below, does not crash the bot — but we keep the real error to log it */ }

let userClient = null;
let userClientReady = false;
const USER_MAX_FILE_BYTES = Number(process.env.USER_MAX_FILE_BYTES) || 500 * 1024 * 1024; // 500MB default — full Nitro ceiling; lower via env if your account isn't full Nitro

async function initUserRelay() {
  if (!process.env.USER_TOKEN) {
    log('[UserRelay] USER_TOKEN not set — big-file relay disabled, clone will link oversized files instead', 'info');
    return;
  }
  if (!_SelfBotLib) {
    log(`[UserRelay] USER_TOKEN is set but discord.js-selfbot-v13 failed to load: ${_selfBotLoadError?.code ?? ''} ${_selfBotLoadError?.message ?? 'unknown error'}. Run: npm install discord.js-selfbot-v13`, 'error');
    return;
  }
  try {
    userClient = new _SelfBotLib.Client();
    userClient.on('ready', () => {
      userClientReady = true;
      log(`[UserRelay] connected as ${userClient.user?.tag ?? 'unknown account'}`, 'success');
    });
    userClient.on('disconnect', () => { userClientReady = false; });
    userClient.on('error', (e) => log(`[UserRelay] error: ${e.message}`, 'error'));
    await userClient.login(process.env.USER_TOKEN);
  } catch (e) {
    log(`[UserRelay] login failed: ${e.stack ?? e.message}`, 'error');
    userClient = null;
    userClientReady = false;
  }
}

