    const lines = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 15).map(([w, c]) => `**${w}** — ${c}`);
    return message.reply({ embeds: [{ color: PINK, title: "Word Frequency", description: lines.join("\n") }] });
